UPDATE HDOC_ADCA_MODIFICATION
SET NEWVAL = #{modifiedValue}
WHERE SERIE = #{chassisSerie}
  AND CHNO = #{chassisNo}
  AND STA = '0'
  AND NEWVAL = #{currentValue}

UPDATE HDOC_ADCA_MODIFICATION
SET NEWVAL = #{modifiedValue}
WHERE SERIE = #{chassisSerie}
  AND CHNO = #{chassisNo}
  AND VARIABLE = #{variable}
  AND STA = '0'
  AND NEWVAL = #{currentValue}
